    errors.push({ field: 'body', message: 'body must be a JSON object' });
    return { errors };
  }

  for (const key of Object.keys(parsed)) {
    if (!ALLOWED_FIELDS.has(key)) errors.push({ field: key, message: 'unknown field' });
  }

  const { input, steps, failAttempts } = parsed;
  if (input === undefined) {
    errors.push({ field: 'input', message: 'is required' });
  } else if (typeof input !== 'string') {
    errors.push({ field: 'input', message: 'must be a string' });
  } else if (input.length < 1 || input.length > MAX_INPUT_LENGTH) {
    errors.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (input.trim() === '') {
    errors.push({ field: 'input', message: 'must not be blank' });
  }

  const stepsValue = steps === undefined ? DEFAULT_STEPS : steps;
  if (!isIntegerIn(stepsValue, MIN_STEPS, MAX_STEPS)) {
    errors.push({ field: 'steps', message: `must be an integer from ${MIN_STEPS} to ${MAX_STEPS}` });
  }

  const failValue = failAttempts === undefined ? 0 : failAttempts;
  if (!isIntegerIn(failValue, MIN_FAIL_ATTEMPTS, MAX_FAIL_ATTEMPTS)) {
    errors.push({ field: 'failAttempts', message: `must be an integer from ${MIN_FAIL_ATTEMPTS} to ${MAX_FAIL_ATTEMPTS}` });
  }

  if (errors.length > 0) return { errors };
  return {
    job: { input: input as string, steps: stepsValue as number, failAttempts: failValue as number },
    idemKey,
  };
}

type CreateOutcome = { kind: 'created' | 'replay'; job: Job } | { kind: 'conflict' };

/** Inserts a job, or returns the one an idempotency key already points to. Runs in one transaction. */
function createJob(job: NewJob, idemKey: string | undefined): CreateOutcome {
  const payload = JSON.stringify({ input: job.input, steps: job.steps, failAttempts: job.failAttempts });
  return transaction(db, (): CreateOutcome => {
    if (idemKey !== undefined) {
      const existing = db.prepare('SELECT payload, job_id FROM idempotency_keys WHERE idem_key = ?').get(idemKey) as
        | { payload: string; job_id: string }
        | undefined;
      if (existing) {
        if (existing.payload !== payload) return { kind: 'conflict' };
        const row = getJobRow(db, existing.job_id);
        if (!row) throw new Error(`idempotency key ${idemKey} points to missing job ${existing.job_id}`);
        return { kind: 'replay', job: rowToJob(row) };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress, output, error, run_after, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, NULL, NULL, 0, ?, ?)`,
    ).run(id, job.input, job.steps, job.failAttempts, now, now);
    if (idemKey !== undefined) {
      db.prepare('INSERT INTO idempotency_keys (idem_key, payload, job_id) VALUES (?, ?, ?)').run(idemKey, payload, id);
    }
    const row = getJobRow(db, id)!;
    return { kind: 'created', job: rowToJob(row) };
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const result = validateSubmission(req, raw);
  if ('errors' in result) {
    sendError(res, 400, 'invalid_request', 'The request is invalid.', result.errors);
    return;
  }
  const outcome = createJob(result.job, result.idemKey);
  if (outcome.kind === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  sendJson(res, outcome.kind === 'created' ? 201 : 200, outcome.job);
}

function handleList(res: ServerResponse): void {
  const rows = db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
  sendJson(res, 200, { jobs: rows.map(rowToJob) });
}

function handleGet(res: ServerResponse, id: string): void {
  const row = getJobRow(db, id);
  if (!row) {
    sendError(res, 404, 'not_found', `No job with id ${id}.`);
    return;
  }
  sendJson(res, 200, rowToJob(row));
}

function handleHealth(res: ServerResponse): void {
  const hb = db.prepare('SELECT at FROM heartbeat WHERE id = 1').get() as { at: number } | undefined;
  const up = hb !== undefined && Date.now() - hb.at < WORKER_STALE_MS;
  sendJson(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');
  const method = req.method ?? 'GET';

  let methods: Record<string, () => void | Promise<void>> | undefined;
  const jobMatch = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (pathname === '/') {
    methods = { GET: () => sendHtml(res) };
  } else if (pathname === '/health') {
    methods = { GET: () => handleHealth(res) };
  } else if (pathname === '/api/jobs') {
    methods = { GET: () => handleList(res), POST: () => handleCreate(req, res) };
  } else if (jobMatch) {
    const id = safeDecode(jobMatch[1]!);
    methods = { GET: () => handleGet(res, id) };
  }

  if (!methods) {
    sendError(res, 404, 'not_found', 'Not found.');
    return;
  }
  if (!Object.hasOwn(methods, method)) {
    sendError(res, 405, 'method_not_allowed', `Method ${method} is not allowed here.`);
    return;
  }
  await methods[method]!();
}

const server = createServer(async (req, res) => {
  try {
    await route(req, res);
  } catch (e) {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
    else res.end();
  }
});

let closing = false;
function shutdown(): void {
  if (closing) return;
  closing = true;
  const force = setTimeout(() => process.exit(0), 2000);
  server.close(() => {
    clearTimeout(force);
    db.close();
    process.exit(0);
  });
  // Keep-alive connections would otherwise hold the close open.
  server.closeAllConnections?.();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

const port = Number(process.env.PORT ?? 3000);
server.listen(port, () => console.log(`server listening on ${port}`));

