import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, transaction, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 500;
const RETRY_DELAY_MS = 500;
/** A job whose simulated failure hits this attempt number is failed for good. */
const MAX_ATTEMPTS = 3;
const FORCE_EXIT_MS = 3000;

const db = openDatabase();
let stopping = false;

interface ClaimedJob {
  id: string;
  input: string;
  steps: number;
}

function nowIso(): string {
  return new Date().toISOString();
}

function writeHeartbeat(at: number): void {
  try {
    db.prepare('INSERT INTO heartbeat (id, at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET at = excluded.at').run(at);
  } catch (e) {
    console.error('heartbeat write failed:', e);
  }
}

/**
 * Startup recovery. This worker is the only one, so any row still `running` was orphaned by a
 * previous process. Attempts are not undone: the crashed attempt counts as started.
 */
function recoverOrphans(): void {
  transaction(db, () => {
    db.prepare("UPDATE jobs SET status = 'queued', progress = 0, run_after = 0, updated_at = ? WHERE status = 'running'").run(nowIso());
  });
}

/**
 * Takes the oldest eligible queued job. If its next attempt is a simulated failure, that attempt is
 * resolved here, before any progress: it is requeued with a delay, or failed on the third attempt.
 */
function claimNext(): ClaimedJob | undefined {
  return transaction(db, () => {
    const now = Date.now();
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1")
      .get(now) as unknown as JobRow | undefined;
    if (!row) return undefined;

    const attempt = row.attempts + 1;
    const ts = nowIso();
    if (attempt <= row.fail_attempts) {
      if (attempt < MAX_ATTEMPTS) {
        db.prepare("UPDATE jobs SET status = 'queued', attempts = ?, progress = 0, run_after = ?, updated_at = ? WHERE id = ?").run(
          attempt,
          now + RETRY_DELAY_MS,
          ts,
          row.id,
        );
      } else {
        db.prepare(
          "UPDATE jobs SET status = 'failed', attempts = ?, progress = 0, output = NULL, error = 'transient failure', run_after = 0, updated_at = ? WHERE id = ?",
        ).run(attempt, ts, row.id);
      }
      return undefined;
    }

    db.prepare("UPDATE jobs SET status = 'running', attempts = ?, progress = 0, run_after = 0, updated_at = ? WHERE id = ?").run(
      attempt,
      ts,
      row.id,
    );
    return { id: row.id, input: row.input, steps: row.steps };
  });
}

/** Puts a job back in the queue after an interrupted run. Its attempt stays counted. */
function requeue(id: string): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress = 0, updated_at = ? WHERE id = ? AND status = 'running'").run(nowIso(), id);
}

async function runAttempt(job: ClaimedJob): Promise<void> {
  for (let i = 1; i <= job.steps; i++) {
    await sleep(STEP_MS);
    if (stopping) {
      requeue(job.id);
      return;
    }
    db.prepare("UPDATE jobs SET progress = ?, updated_at = ? WHERE id = ? AND status = 'running'").run(i, nowIso(), job.id);
  }
  db.prepare(
    "UPDATE jobs SET status = 'completed', progress = ?, output = ?, updated_at = ? WHERE id = ? AND status = 'running'",
  ).run(job.steps, job.input.toUpperCase(), nowIso(), job.id);
}

function requestStop(): void {
  if (stopping) return;
  stopping = true;
  // The loop checks `stopping` between steps and polls, so this only bounds a stuck shutdown.
  setTimeout(() => process.exit(0), FORCE_EXIT_MS);
}
process.on('SIGTERM', requestStop);
process.on('SIGINT', requestStop);

writeHeartbeat(Date.now());
recoverOrphans();
const heartbeat = setInterval(() => writeHeartbeat(Date.now()), HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  let job: ClaimedJob | undefined;
  try {
    job = claimNext();
  } catch (e) {
    console.error('claim failed, retrying:', e);
    await sleep(POLL_MS);
    continue;
  }
  if (!job) {
    await sleep(POLL_MS);
    continue;
  }
  try {
    await runAttempt(job);
  } catch (e) {
    console.error(`attempt for job ${job.id} failed:`, e);
    await sleep(POLL_MS);
  }
}

clearInterval(heartbeat);
writeHeartbeat(0);
db.close();
console.log('worker stopped');
process.exit(0);

